WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (55::BIGINT, 'Es uno de los peores profes que he tenido en mi vida, no es claro, las prácticas, tareas, trabajos y examenes no tiene instrucciones o no son claras, cuando le haces pregunta no te contesta o te contesta con una pregunta que te deja más confuso, NO MATRICULEN CON EL, el mae es un desorganizado.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b19985b5ee1c8bbd4b8900da71bc398695e7ad3f98f8362c26fce36e32acfc4b'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'el "profesor" no responde preguntas y si las responde es con otras preguntas, pasa haciendo practicas innecesarias y que muchas veces no explica bien por tratar de explicar 2 o mas cosas al mismo tiempo, si tienen la oportunidad de matricular con el, desaprovéchenla porque no se aprende mucho'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2026-06-04T00:00:00+00:00'::TIMESTAMPTZ, '79a462e524d16cf99af341958a497b390c5b238195903f456b95622dfe6dbd63'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Es muy buen profe. Al ser las clases largas, se hace aburrido y cansado. La materia es aburrida realmente, y no es culpa de él. Es nada más de poner de su parte. Sí lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-05-28T00:00:00+00:00'::TIMESTAMPTZ, '5497885b579a64d9bc925af6b7b70ab90c268cb0a1bb38c3c49bfd2d9be7c896'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Terrible'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-30T00:00:00+00:00'::TIMESTAMPTZ, '096c3f859d57f73e655386c7208b98c788001d38d236e8cfa68cd7d6c1e79947'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'El profesor intenta abarcar todos los temas de manera completa, y si se aprende bastante por lo que cumple su objetivo. Pero, no responde de manera adecuada las preguntas de los estudiantes, es irónico, no se entiende ni el mismo y es complicado aprender así. No lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-04-25T00:00:00+00:00'::TIMESTAMPTZ, '394c4dcc947058aa03da02acd56432d6d8185c388f1da493cfa0d019f9074dbd'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'no matriculen con este mae no sabe explicar, nunca es claro en lo que dice es malo al dar instrucciones y pretende que uno entienda todo solo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-04-23T00:00:00+00:00'::TIMESTAMPTZ, '85d3f9b614b31917d026c52ac8423b31210b72fb5962d4ca5ff57275980ee300'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Si usted pone de su parte le va a ir bien, el profe es bueno y deja mucha práctica, pero a veces las instrucciones de los trabajos no son muy claras.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '58bf0e791868bad7d30fc9b69e432d6a8cd6aab9c66173e11e4830ba882fe069'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'No brinda respuesta a las preguntas siempre, prefiere repreguntarle a uno (si uno pregunta es por algo). Los trabajos grupales se desmoronan constantemente porque no siempre hay claridad. Los exámenes también tienen complejidad.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2024-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'c97f002974f7c324df0d3cdfc9f047eabfd73284ad3f3f058c44cf4aff13522b'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'El mae responde cuando le da la gana, si es que responde. Creo que como docente es fundamental responder cuando algún alumno tiene alguna duda o solicitud. Las clases son súper aburridas, habla demasiado bajo por lo que no se escucha cuando "explica". Muy desorganizado con los trabajos y fechas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a3a5d14516d71bb0d623ee120e4d06bc1e864e8301f6ef06ba9dfd63dd3f7e1d'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'No les recomiendo matricular con el, si uno pregunta evade las cosas y espera a que uno este enterado, cuando en realidad el tiene la obligación como profesor de enseñar todo aquello que no nos quede claro'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'da9a4648f0fc216732d7fdf7b2f331b657d5720590ac81f127f8b1e255ea4da7'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Sinceramente fue un error haber matriculado con el, no entendí nada de la clases, ya que a veces hasta se enredaba todo, se pasa siempre de la hora de salida, es el profesor que se aprovecha que es virtual y deja trabajos súper largos y uno ni entiende y da sueño.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, '33b7cf78f7127903885be530400db8781a4846a9e0cf73524c95a1df9c8000cc'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Si usted se quiere castigar, matricule con este profesor. No sabe explicar, se enreda solo y la peor parte es el tono de voz, da sueño. Hay que poner demasiada atención para lograr entender algo, se pasa de la hora de salida hasta media hora y no le importa. Si puede escoger otro profe, ni lo dude.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'd100ed184dead7f7f8d7624f7794c6f020c2929f99750e6bde6646137d78f0d3'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Pésimo profesor, clases súper largas, califica demasiado lento, deja demasiados trabajos, si les cuesta computación ni se les ocurra este profe, no se aprende nada'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'e8111579af9e9153bdba761eb3439813c39d1cf2028c1f5c34f6cdb0c06c9943'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Él profe intenta explicar los temas desde todas las aristas, pero el se termina confundiendo y termina confundiendo a todos, tiene muy mala forma de redactar entonces a veces uno no sabe qué quiere decir en un proyecto o examen'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '77e9a46033e736f1e4827bcc6d98df1b864614343491b5fedfdcd7b532b1ad85'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Es un profesor bastante bueno. Sin embrago, deja muchas asignaciones y los examenes tienen su complejidad.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '61e0d7fd6fe79c630beba1ae5d20ca8de6d0ab18bd26beedc098240671d8d492'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Es buen profesor pero para el sistema de evalucación es muy lento en calificar y deja asignasiones con una dificultad considerable. (si le cuesta computación mejor pienselo dos veces)'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '759516b9ef49e0245b36c0bee417ffc1dc8648290f676e2e8575ae85f161f8dd'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Es buena Persona pero deja la materia poco clara'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'c9e32f38cefc2f032b6636e7c5ea4f3cab8d5c5c8513953a67b55ae0b181b7d4'::TEXT, ARRAY[2376]::BIGINT[]),
    (55::BIGINT, 'Excelente persona, llega tarde, mucha participacion en clase, estudiar bastante para el examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2018-04-13T00:00:00+00:00'::TIMESTAMPTZ, '44756e7d4c5ecb12e05fff5bb442fdd533e6807672893fb0ed2248a37827cc64'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Buen profesor, el curso es muy teórico pero el trata de que sea lo mas participativo posible, si ud participa bastante va salir bien, ya que casi todo lo que entra en los examenes lo saca de lo que hace en clase. pst: suele llegar tarde a clases'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e945852ea722ddc84774b96d2f774ddf70c7e74a0d639226ae5b346f1ecc057b'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '485356556ee2ab2f38da3630e17bff31fef8b1bb79cd11f113a78e9aab284e25'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Buen profesor, aunque le encanta llegar tarde. Sus exámenes son diferentes, pero de buena manera. Se tiene que leer bastante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a76e01706e59e6561055e26bd44ec3b2aecfeadcc8cf4bc975c5c2a11609804d'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Excelente profesor y excelente persona, los exámenes no son tan difíciles y hace todo lo posible para que los estudiantes comprendan toda la materia a la perfección, muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '142bd23bbab368b5892229a95b3dc4744abfc0a2d6d99f9534d4a2a6f372a239'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'muy buen profe,aunque el curso es muy teórico, él lo lleva más allá y hace que los estudiantes analicen. Y como persona es excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, '3aaf2fad08f15976bfc37f0a53d6c17f46dfc8ee70e66fe38cf4b2a59af2ea0b'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Es muy bueno como profesor y como persona. Enseña muchas cosas, da muy buenos consejos. Es muy directo para hablar y para algunos eso puede resultar hiriente. Sobre todo a la hora de calificar exposiciones, dice las cosas sin rodeos y al frente de todos. Es un poco irresponsable y suele llegar tarde'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fafb1608b6543b072cd2e772b41c260c99abfd4761eef259cd810aef98544f5f'::TEXT, ARRAY[2509]::BIGINT[]),
    (55::BIGINT, 'Excelente profe, las clases son divertidas y el profe es muy pura vida'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '88103b9248b525ac8670c87ea045e2b8fd9a3c09c893a8481c6b9235ab614004'::TEXT, ARRAY[2509]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
